public class T {
  static String run(int q) {
    StringBuilder sb = new StringBuilder();
    switch(q)
    {
    case 1: sb.append("apple"); break;
    case 2: sb.append("orange"); break;
    case 3: sb.append("banana"); break;
    case 4: sb.append("pear");
    case 5: sb.append("grapes");
    default: sb.append("kiwi");
    }
    return sb.toString();
  }
  public static void main(String[] a) {
    int[] qs = {-3, 0, 1, 2, 3, 4, 5, 6};
    StringBuilder bad = new StringBuilder();
    for (int q : qs) {
      boolean kiwi = run(q).contains("kiwi");
      boolean expect = (q < 1 || q >= 4);
      if (kiwi != expect) bad.append(q).append(" ");
    }
    String pick = bad.length() == 0 ? "Any integer less than 1 and greater than or equal to 4." : "other:" + bad;
    System.out.print(pick);
  }
}
